code.cpp:
class Solution {
public:
    int minFlipsMonoIncr(string s) {
        int ans = 0;
        int ones = 0;
        for (char c : s) {
            if (c == '1') {
                ones++;
            } else {
                ans = min(ans + 1, ones);
            }
        }
        return ans;
    }
};
